const TEMPO = {'Crescendo': 137.14, 'Crescendo 2': 137.14, 'Mellotron': 120, 'Riff 7/8': 137.14, 'Strofa 7/8': 137.14, 'Ponte 5/4': 96, 'Assolo 4/4': 124, 'Riff ripresa': 137.14, 'Finale': [[1,120],[1,110.67],[1,101.33],[1,92]], 'Strip': 120}

// section lanes: 1 plays, 0 is silent, values in between fade
const section1 = "<1!26 0!86>"  // Crescendo · 26 (7/8) bars · 120 BPM · A · Am
const section2 = "<0!26 1!35 0!51>"  // Crescendo 2 · 35 (7/8) bars · 120 BPM · A · Am C D F
const section3 = "<0!61 1!4 0!47>"  // Mellotron · 4 bars · 120 BPM · A · Am G F E
const section4 = "<0!65 1!8 0!39>"  // Riff 7/8 · 8 (7/8) bars · 120 BPM · A · Am C D F
const section5 = "<0!73 1!8 0.5 0!30>"  // Strofa 7/8 · 8 (7/8) bars · 120 BPM · A · Am C D F
const section6 = "<0!81 0.5 1!5 0!25>"  // Ponte 5/4 · 6 (5/4) bars · 120 BPM · A · Am G F E · fades in over 1 bars
const section7 = "<0!87 1!8 0!17>"  // Assolo 4/4 · 8 bars · 124 BPM · A · Am G F E
const section8 = "<0!95 1!4 0!13>"  // Riff ripresa · 4 (7/8) bars · 120 BPM · A · Am C D F
const section9 = "<0!99 1!4 0!9>"  // Finale · 4 bars · 120→92 BPM · A · Am G F E
const section10 = "<0!103 1!9>"  // Strip · 9 bars · 120 BPM · A · Am G F E

// ========== drums ==========
// Crescendo · bars 1-26 · pattern B
// Drums · AkaiXR10
$: s("bd ~ ~ ~ ~ ~ ~ ~ bd ~ ~ ~ ~ ~").bank("AkaiXR10").gain(0.9).lpf(2000).mask(section1).velocity(section1).orbit(1).analyze("kick")
$: s("~ ~ ~ ~ sd ~ ~ ~ ~ ~ ~ ~ sd ~").bank("AkaiXR10").gain(0.68).lpf(2000).mask(section1).velocity(section1).orbit(1).analyze("snare")
$: s("rd ~ rd ~ rd ~ rd ~ rd ~ rd ~ rd ~").bank("AkaiXR10").gain(0.32).lpf(2000).mask(section1).velocity(section1).orbit(1).analyze("hats")
// Crescendo 2 · bars 27-61 · pattern B
$: s("bd ~ ~ ~ ~ ~ ~ ~ bd ~ ~ ~ ~ ~").bank("AkaiXR10").gain(0.9).lpf(2000).mask(section2).velocity(section2).orbit(1).analyze("kick")
$: s("~ ~ ~ ~ sd ~ ~ ~ ~ ~ ~ ~ sd ~").bank("AkaiXR10").gain(0.68).lpf(2000).mask(section2).velocity(section2).orbit(1).analyze("snare")
$: s("rd ~ rd ~ rd ~ rd ~ rd ~ rd ~ rd ~").bank("AkaiXR10").gain(0.32).lpf(2000).mask(section2).velocity(section2).orbit(1).analyze("hats")
// Riff 7/8 · bars 66-73 · pattern A
$: s("bd ~ ~ ~ ~ ~ ~ ~ bd ~ ~ ~ ~ ~").bank("AkaiXR10").gain(0.9).lpf(2000).mask(section4).velocity(section4).orbit(1).analyze("kick")
$: s("~ ~ ~ ~ sd ~ ~ ~ ~ ~ ~ ~ sd ~").bank("AkaiXR10").gain(0.68).lpf(2000).mask(section4).velocity(section4).orbit(1).analyze("snare")
$: s("hh ~ hh ~ hh ~ hh ~ hh ~ hh ~ hh ~").bank("AkaiXR10").gain(0.45).lpf(2000).mask(section4).velocity(section4).orbit(1).analyze("hats")
$: s("cr").bank("AkaiXR10").gain(.55).room(.4).mask("<0 1 0!6>").mask(section4).velocity(section4).orbit(1).analyze("fx")
// Strofa 7/8 · bars 74-81 · pattern B
$: s("bd ~ ~ ~ ~ ~ ~ ~ bd ~ ~ ~ ~ ~").bank("AkaiXR10").gain(0.9).lpf(2000).mask(section5).velocity(section5).orbit(1).analyze("kick")
$: s("~ ~ ~ ~ sd ~ ~ ~ ~ ~ ~ ~ sd ~").bank("AkaiXR10").gain(0.68).lpf(2000).mask(section5).velocity(section5).orbit(1).analyze("snare")
$: s("rd ~ rd ~ rd ~ rd ~ rd ~ rd ~ rd ~").bank("AkaiXR10").gain(0.32).lpf(2000).mask(section5).velocity(section5).orbit(1).analyze("hats")
// Ponte 5/4 · bars 82-87 · pattern C
$: s("[bd ~ ~ ~] ~ [~ ~ bd ~] ~ ~").bank("AkaiXR10").gain(0.9).lpf(2000).mask(section6).velocity(section6).orbit(1).analyze("kick")
$: s("~ [sd ~ ~ ~] ~ [sd ~ ~ ~] [sd ~ ~ ~]").bank("AkaiXR10").gain(0.68).lpf(2000).mask(section6).velocity(section6).orbit(1).analyze("snare")
