$: s("sd*20").bank("AkaiXR10").gain(saw.range(.15, .75)).mask("<0!2 1 0!3>").mask(section6).velocity(section6).orbit(1).analyze("snare")
// Assolo 4/4 · bars 88-95 · pattern D
$: s("[bd ~ ~ ~] ~ [bd ~ bd ~] ~").bank("AkaiXR10").gain(0.9).lpf(2000).mask(section7).velocity(section7).orbit(1).analyze("kick")
$: s("~ [sd ~ ~ ~] ~ [sd ~ ~ ~]").bank("AkaiXR10").gain(0.68).lpf(2000).mask(section7).velocity(section7).orbit(1).analyze("snare")
$: s("[hh ~ hh ~] [hh ~ hh ~] [hh ~ hh ~] [hh ~ hh ~]").bank("AkaiXR10").gain(0.45).lpf(2000).mask(section7).velocity(section7).orbit(1).analyze("hats")
$: s("~ ~ ~ [~ ~ oh ~]").bank("AkaiXR10").gain(0.41).lpf(2000).mask(section7).velocity(section7).orbit(1).analyze("hats")
$: s("sd*16").bank("AkaiXR10").gain(saw.range(.15, .75)).mask("<0!6 1 0>").mask(section7).velocity(section7).orbit(1).analyze("snare")
$: s("cr").bank("AkaiXR10").gain(.55).room(.4).mask("<0!7 1>").mask(section7).velocity(section7).orbit(1).analyze("fx")
// Riff ripresa · bars 96-99 · pattern A
$: s("bd ~ ~ ~ ~ ~ ~ ~ bd ~ ~ ~ ~ ~").bank("AkaiXR10").gain(0.9).lpf(2000).mask(section8).velocity(section8).orbit(1).analyze("kick")
$: s("~ ~ ~ ~ sd ~ ~ ~ ~ ~ ~ ~ sd ~").bank("AkaiXR10").gain(0.68).lpf(2000).mask(section8).velocity(section8).orbit(1).analyze("snare")
$: s("hh ~ hh ~ hh ~ hh ~ hh ~ hh ~ hh ~").bank("AkaiXR10").gain(0.45).lpf(2000).mask(section8).velocity(section8).orbit(1).analyze("hats")
$: s("cr").bank("AkaiXR10").gain(.55).room(.4).mask("<0!3 1>").mask(section8).velocity(section8).orbit(1).analyze("fx")
// Finale · bars 100-103 · pattern E
$: s("[bd ~ ~ ~] ~ [bd ~ ~ ~] ~").bank("AkaiXR10").gain("<0.73 0.57 0.4 0.9>").lpf(2000).mask(section9).velocity(section9).orbit(1).analyze("kick")
$: s("~ ~ [sd ~ ~ ~] ~").bank("AkaiXR10").gain("<0.55 0.43 0.3 0.68>").lpf(2000).mask(section9).velocity(section9).orbit(1).analyze("snare")
$: s("[rd ~ ~ ~] [rd ~ ~ ~] [rd ~ ~ ~] [rd ~ ~ ~]").bank("AkaiXR10").gain("<0.26 0.2 0.14 0.32>").lpf(2000).mask(section9).velocity(section9).orbit(1).analyze("hats")
$: s("cr").bank("AkaiXR10").gain(.55).room(.4).mask("<0!3 1>").mask(section9).velocity(section9).orbit(1).analyze("fx")
// Strip · bars 104-112 · pattern E
$: s("[bd ~ ~ ~] ~ [bd ~ ~ ~] ~").bank("AkaiXR10").gain("<0.59 0.53 0.46 0.4 0.9 0.84 0.78 0.71 0.65>").lpf(2000).mask(section10).velocity(section10).orbit(1).analyze("kick")
$: s("~ ~ [sd ~ ~ ~] ~").bank("AkaiXR10").gain("<0.44 0.39 0.35 0.3 0.68 0.63 0.58 0.53 0.49>").lpf(2000).mask(section10).velocity(section10).orbit(1).analyze("snare")
$: s("[rd ~ ~ ~] [rd ~ ~ ~] [rd ~ ~ ~] [rd ~ ~ ~]").bank("AkaiXR10").gain("<0.21 0.18 0.16 0.14 0.32 0.29 0.27 0.25 0.23>").lpf(2000).mask(section10).velocity(section10).orbit(1).analyze("hats")

// ========== guitar ==========
// Crescendo · bars 1-26 · pattern B
// Guitar · Crunch, Held
$: note("<[a2,e3,a3]>")
  .s("gm_overdriven_guitar,sawtooth").attack(.003).decay(1.5).sustain(0.8).release(.08)
  .distort(1.5).distortvol(.2).hpf(70).lpf(4200).jux(x => x.late(.012))
  .room(.1).gain(.8).mask(section1).postgain(section1.mul(0.55)).orbit(5).analyze("guitar")
// Crescendo 2 · bars 27-61 · pattern B
$: note("<[d3,a3,d4] [f2,c3,f3] [a2,e3,a3] [c3,g3,c4]>")
  .s("gm_overdriven_guitar,sawtooth").attack(.003).decay(1.5).sustain(0.8).release(.08)
  .distort(1.5).distortvol(.2).hpf(70).lpf(4200).jux(x => x.late(.012))
  .room(.1).gain(.8).mask(section2).postgain(section2.mul(0.55)).orbit(5).analyze("guitar")
// Riff 7/8 · bars 66-73 · pattern A
// Guitar · Distorted, Riff
$: note("<[f2,c3,f3] [a2,e3,a3] [c3,g3,c4] [d3,a3,d4]>").struct("x ~ x x ~ x ~ x x ~ x ~ x x")
  .s("gm_distortion_guitar,sawtooth").attack(.003).decay(0.09).sustain(0).release(.08)
  .distort(3).distortvol(.2).hpf(80).lpf(4200).jux(x => x.late(.012))
  .room(.1).gain(.8).mask(section4).postgain(section4.mul(0.8)).orbit(5).analyze("guitar")
// Strofa 7/8 · bars 74-81 · pattern B
// Guitar · Crunch, Held
$: note("<[f2,c3,f3] [a2,e3,a3] [c3,g3,c4] [d3,a3,d4]>")
  .s("gm_overdriven_guitar,sawtooth").attack(.003).decay(1.5).sustain(0.8).release(.08)
  .distort(1.5).distortvol(.2).hpf(70).lpf(4200).jux(x => x.late(.012))
  .room(.1).gain(.8).mask(section5).postgain(section5.mul(0.55)).orbit(5).analyze("guitar")
// Assolo 4/4 · bars 88-95 · pattern C
// Guitar · Crunch, Power chords, 8ths
$: note("<[g2,d3,g3] [f2,c3,f3] [e2,b2,e3] [a2,e3,a3]>").struct("[x x] [x x] [x x] [x x]")
  .s("gm_overdriven_guitar,sawtooth").attack(.003).decay(0.3).sustain(0.55).release(.08)
  .distort(1.5).distortvol(.2).hpf(70).lpf(4200).jux(x => x.late(.012))
  .room(.1).gain(.8).mask(section7).postgain(section7.mul(0.7)).orbit(5).analyze("guitar")
// Riff ripresa · bars 96-99 · pattern A
// Guitar · Distorted, Riff
$: note("<[c3,g3,c4] [d3,a3,d4] [f2,c3,f3] [a2,e3,a3]>").struct("x ~ x x ~ x ~ x x ~ x ~ x x")
  .s("gm_distortion_guitar,sawtooth").attack(.003).decay(0.09).sustain(0).release(.08)
  .distort(3).distortvol(.2).hpf(80).lpf(4200).jux(x => x.late(.012))
  .room(.1).gain(.8).mask(section8).postgain(section8.mul(0.85)).orbit(5).analyze("guitar")
// Finale · bars 100-103 · pattern B
// Guitar · Distorted, Held
$: note("<[g2,d3,g3] [f2,c3,f3] [e2,b2,e3] [a2,e3,a3]>")
  .s("gm_distortion_guitar,sawtooth").attack(.003).decay(1.5).sustain(0.8).release(.08)
  .distort(3).distortvol(.2).hpf(80).lpf(4200).jux(x => x.late(.012))
  .room(.1).gain(.8).mask(section9).postgain(section9.mul("<0.58 0.37 0.15 0.8>")).orbit(5).analyze("guitar")
// Strip · bars 104-112 · pattern B
$: note("<[g2,d3,g3] [f2,c3,f3] [e2,b2,e3] [a2,e3,a3]>")
  .s("gm_distortion_guitar,sawtooth").attack(.003).decay(1.5).sustain(0.8).release(.08)
  .distort(3).distortvol(.2).hpf(80).lpf(4200).jux(x => x.late(.012))
  .room(.1).gain(.8).mask(section10).postgain(section10.mul("<0.39 0.31 0.23 0.15 0.8 0.72 0.64 0.56 0.48>")).orbit(5).analyze("guitar")

// ========== arp ==========
// Crescendo · bars 1-26 · pattern A
// Arpeggio · Up, 8ths
$: note("<[a3 c4 e4 a4 a3 c4 e4]>")
  .s("gm_rock_organ").lpf(890).lpq(1)
  .decay(.15).sustain(.15).gain(0.4).degradeBy(0.15).mask(section1).velocity(section1).orbit(3).analyze("arp")
// Crescendo 2 · bars 27-61 · pattern A
$: note("<[a3 d4 f#4 a4 a3 d4 f#4] [f3 a3 c4 f4 f3 a3 c4] [a3 c4 e4 a4 a3 c4 e4] [g3 c4 e4 g4 g3 c4 e4]>")
  .s("gm_rock_organ").lpf(890).lpq(1)
  .decay(.15).sustain(.15).gain(0.4).degradeBy(0.15).mask(section2).velocity(section2).orbit(3).analyze("arp")
// Strofa 7/8 · bars 74-81 · pattern A
$: note("<[f3 a3 c4 f4 f3 a3 c4] [a3 c4 e4 a4 a3 c4 e4] [g3 c4 e4 g4 g3 c4 e4] [a3 d4 f#4 a4 a3 d4 f#4]>")
  .s("gm_rock_organ").lpf(890).lpq(1)
  .decay(.15).sustain(.15).gain(0.4).degradeBy(0.15).mask(section5).velocity(section5).orbit(3).analyze("arp")
// Ponte 5/4 · bars 82-87 · pattern B
// Arpeggio · Broken, 16ths
$: note("<[g#3 e4 b3 g#4 e4 g#3 g#4 b3 g#3 e4 b3 g#4 e4 g#3 g#4 b3 g#3 e4 b3 g#4] [a3 e4 c4 a4 e4 a3 a4 c4 a3 e4 c4 a4 e4 a3 a4 c4 a3 e4 c4 a4] [g3 d4 b3 g4 d4 g3 g4 b3 g3 d4 b3 g4 d4 g3 g4 b3 g3 d4 b3 g4] [f3 c4 a3 f4 c4 f3 f4 a3 f3 c4 a3 f4 c4 f3 f4 a3 f3 c4 a3 f4]>")
  .s("gm_electric_guitar_clean").lpf(890).lpq(1)
  .decay(.15).sustain(.15).gain(0.3).degradeBy(0.15).mask(section6).velocity(section6).orbit(3).analyze("arp")
// Riff ripresa · bars 96-99 · pattern C
// Arpeggio · Pulsar, 8ths
$: note("<[g3 g4 c4 g4 e4 g4 c4] [a3 a4 d4 a4 f#4 a4 d4] [f3 f4 a3 f4 c4 f4 a3] [a3 a4 c4 a4 e4 a4 c4]>")
  .s("gm_rock_organ").lpf(890).lpq(1)
  .decay(.15).sustain(.15).gain(0.38).degradeBy(0.15).mask(section8).velocity(section8).orbit(3).analyze("arp")

